window.docContents[61].resolve({"/6___-Quiver-representations/6___1___-Problems/Problem-6___1___3___-Dynkin-diagrams/#Chapter6___Problem6___1___3":{"contents":"Problem 6.1.3. Dynkin diagrams. Let \\Gamma be a graph, i.e., a finite set of points (vertices) connected with a certain number of edges (we allow multiple edges). We assume that \\Gamma is connected (any vertex can be connected to any other by a path of edges) and has no self-loops (edges from a vertex to itself). Suppose the vertices of \\Gamma are labeled by integers 1, \\ldots, n. Then one can assign to \\Gamma an n \\times n matrix R = (r_{ij}), where r_{ij} is the number of edges connecting vertices i and j. This matrix is obviously symmetric and is called the adjacency matrix. Define the matrix A = 2I - R, where I is the identity matrix.\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.1. Problems\tProblem 6.1.3: Dynkin diagrams","header":"Problem 6.1.3: Dynkin diagrams","id":"/6___-Quiver-representations/6___1___-Problems/Problem-6___1___3___-Dynkin-diagrams/#Chapter6___Problem6___1___3"},"/9___-Structure-of-finite-dimensional-algebras/9___7___-Morita-equivalence/Morita-equivalence/#Chapter9___Definition9___7___1":{"contents":"Definition 9.7.1. Finite dimensional algebras A and B are said to be Morita equivalent if the abelian categories A\\text{-fmod} and B\\text{-fmod} are equivalent.\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.7. Morita equivalence\tMorita equivalence","header":"Morita equivalence","id":"/9___-Structure-of-finite-dimensional-algebras/9___7___-Morita-equivalence/Morita-equivalence/#Chapter9___Definition9___7___1"}});
